package com.chatserver.realtime

import java.util.Base64
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.locks.ReentrantReadWriteLock
import sun.misc.Signal
import sun.misc.SignalHandler

data class FeatureFlags(
    val rateLimitEnabled: Boolean = true,
    val maxMessagesPerSecond: Int = 10,
    val auditLogEnabled: Boolean = true,
    val encryptionRequired: Boolean = true,
    val adminBypassAuth: Boolean = false
)

class ChatSession(val userId: String, val isAdmin: Boolean = false) {
    var authenticated: Boolean = false
    var messageCount: Int = 0
    var lastResetTimestamp: Long = System.currentTimeMillis()
}

object FeatureFlagStore {
    private val flags: AtomicReference<FeatureFlags> = AtomicReference(FeatureFlags())
    private val reloadLock = ReentrantReadWriteLock()

    fun getFlags(): FeatureFlags = flags.get()

    fun atomicReload(newFlags: FeatureFlags): Boolean {
        val lock = reloadLock.writeLock()
        if (!lock.tryLock()) {
            // Another reload in progress, reject
            return false
        }
        try {
            if (!validateFlagConsistency(newFlags)) {
                return false
            }
            flags.set(newFlags)
            return true
        } finally {
            lock.unlock()
        }
    }

    private fun validateFlagConsistency(flags: FeatureFlags): Boolean {
        if (flags.adminBypassAuth && !flags.auditLogEnabled) {
            println("REJECTED: admin bypass without audit logging")
            return false
        }
        return true
    }
}

class MessageRouter {
    private val sessions = ConcurrentHashMap<String, ChatSession>()
    private val messageLock = ReentrantReadWriteLock()

    // Securely generated AES-256 key for message encryption.
    private val encryptionKey: SecretKey = KeyGenerator.getInstance("AES").apply {
        init(256)
    }.generateKey()

    private val secureRandom = SecureRandom()

    companion object {
        private const val GCM_IV_LENGTH = 12
        private const val GCM_TAG_LENGTH_BITS = 128
    }

    fun registerSession(session: ChatSession) {
        sessions[session.userId] = session
    }

    fun processMessage(userId: String, message: String): Result<String> {
        val session = sessions[userId] ?: return Result.failure(Exception("No session"))
        val flags = FeatureFlagStore.getFlags()

        if (!checkAuthorization(session, flags)) {
            return Result.failure(Exception("Unauthorized"))
        }

        if (flags.rateLimitEnabled && !checkRateLimit(session, flags)) {
            return Result.failure(Exception("Rate limited"))
        }

        return deliverMessage(session, message, flags)
    }

    private fun checkAuthorization(session: ChatSession, flags: FeatureFlags): Boolean {
        if (session.isAdmin && flags.adminBypassAuth) {
            return true
        }
        return session.authenticated
    }

    private fun checkRateLimit(session: ChatSession, flags: FeatureFlags): Boolean {
        val now = System.currentTimeMillis()
        if (now - session.lastResetTimestamp > 1000) {
            session.messageCount = 0
            session.lastResetTimestamp = now
        }
        session.messageCount++
        return session.messageCount <= flags.maxMessagesPerSecond
    }

    private fun deliverMessage(session: ChatSession, message: String, flags: FeatureFlags): Result<String> {
        val processedMsg = if (flags.encryptionRequired) {
            encryptMessage(message)
        } else {
            message
        }
        if (flags.auditLogEnabled) {
            logMessage(session.userId, processedMsg)
        }
        return Result.success(processedMsg)
    }

    private fun encryptMessage(message: String): String {
        val iv = ByteArray(GCM_IV_LENGTH).also { secureRandom.nextBytes(it) }
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.ENCRYPT_MODE, encryptionKey, GCMParameterSpec(GCM_TAG_LENGTH_BITS, iv))
        val ciphertext = cipher.doFinal(message.toByteArray(Charsets.UTF_8))
        // Prepend IV to ciphertext so it can be decrypted later.
        val combined = ByteArray(iv.size + ciphertext.size)
        System.arraycopy(iv, 0, combined, 0, iv.size)
        System.arraycopy(ciphertext, 0, combined, iv.size, ciphertext.size)
        return "ENC[${Base64.getEncoder().encodeToString(combined)}]"
    }

    private fun logMessage(userId: String, message: String) {
        println("AUDIT: $userId -> $message")
    }
}

class ChatServer {
    private val router = MessageRouter()
    private val running = AtomicBoolean(true)
    private val reloadThread = AtomicReference<Thread?>(null)

    fun start() {
        installSignalHandlers()
        println("Chat server started with flags: ${FeatureFlagStore.getFlags()}")
    }

    private fun installSignalHandlers() {
        Signal.handle(Signal("USR2")) { _ ->
            // Signal handler only sets a flag; actual reload happens on dedicated thread
            scheduleConfigReload()
        }
    }

    private fun scheduleConfigReload() {
        val thread = Thread {
            handleConfigReload()
        }
        thread.isDaemon = true
        if (reloadThread.compareAndSet(null, thread)) {
            thread.start()
            thread.join()
            reloadThread.set(null)
        }
        // If CAS fails, a reload is already in progress — skip
    }

    private fun handleConfigReload() {
        val newFlags = loadFlagsFromConfig()
        val success = FeatureFlagStore.atomicReload(newFlags)
        if (success) {
            println("Config reloaded: ${FeatureFlagStore.getFlags()}")
        } else {
            println("Config reload rejected or concurrent reload in progress")
        }
    }

    private fun loadFlagsFromConfig(): FeatureFlags {
        return FeatureFlags(
            rateLimitEnabled = false,
            maxMessagesPerSecond = 1000,
            auditLogEnabled = true,
            encryptionRequired = false,
            adminBypassAuth = true
        )
    }

    fun getRouter(): MessageRouter = router
}

fun main() {
    val server = ChatServer()
    server.start()

    val adminSession = ChatSession("admin-1", isAdmin = true)
    adminSession.authenticated = false
    server.getRouter().registerSession(adminSession)

    val result = server.getRouter().processMessage("admin-1", "secret data")
    println("Result: $result")
}
